  3	/**
  4	 * A class representing shared characteristics of animals.
  5	 *
  6	 * @version 25/02/2022
  7	 */
  8	public abstract class Animal extends LivingOrganism
  9	{
 10	    // Indicates whether an animal is a female or not;
 11	    protected boolean isFemale;    
 12	    // The age at which an animal can start to breed.
 13	    protected int breedingAge;
 14	    // The age to which an animal can live.
 15	    protected int maxAge;
 16	    // The likelihood of an animal breeding.
 17	    protected double breedingProbability;
 18	    // whther the animal is infected or not
 19	    protected boolean infected;
 20	    // The likelihood of an animal having a disease.
 21	    protected double diseaseProbability;
 22	    // The likelihood of an animal catching a disease from another animal
 23	    protected double diseaseSpreadProbability;
 24	    // The likelihood of an animal dying from catching the disease
 25	    protected double deathFromInfectionProbability;
 26	    // The likelihood of an animal becomming immune to the disease
 27	    protected double immuneProbability;
 28	    // whether the animal is immune or not
 29	    protected boolean immune;
 30	    // The maximum number of births.
 31	    protected int maxLitterSize;
 32	    // The animals's age.
 33	    protected int age;
 34	    // The animals's food level, which is increased by eating prey.
 35	    protected int foodLevel;
 36	    // The maximum food level that an animal will eat at. The food level they will stop
 37	    // being hungry at
 38	    protected int maxFoodLevel;
 39	    // Probability that an animal will move at a given step.
 40	    protected double movementProbability;
 41	    
 42	    /**
 43	     * Create a new animal at location in field.
 44	     * 
 45	     * @param field The field currently occupied.
 46	     * @param location The location within the field.
 47	     * @param infected Intial state if the animal is infected or not
 48	     * @param immmune Intial state if the animal is immune or not
 49	     */
 50	    public Animal(Field field, Location location, boolean infected, boolean immune)
 51	    {
 52	        super(field, location);
 53	        alive = true;
 54	        this.infected = infected;
 55	        this.immune = immune;
 56	        
 57	        diseaseProbability = 0.00000015;
 58	        diseaseSpreadProbability = 0.80;
 59	        deathFromInfectionProbability = 0.13;
 60	        immuneProbability = 0.05;
 61	        
 62	        isFemale = rand.nextBoolean();
 63	    }
 64	    
 65	    /**
 66	     * @Override
 67	     * 
 68	     * Make this animal act - that is: make it do
 69	     * whatever it wants/needs to do.
 70	     * 
 71	     * @param newAnimals A list to receive newly born animals.
 72	     */
 73	    public void act(List<LivingOrganism> newAnimals)
 74	    {
 75	        incrementAge();
 76	        incrementHunger();
 77	        
 78	        // checks to see if the animal is going to die from it infection 
 79	        // or become immune
 80	        // if the animal becomes immune then it no longer is infected
 81	        if (!getIsImmune() && getIsInfected()) 
 82	        {
 83	            if(rand.nextDouble() <= deathFromInfectionProbability) 
 84	            {
 85	                setDead();            
 86	            }
 87	            else if(rand.nextDouble() <= immuneProbability) {
 88	                immune = true;
 89	                infected = false;
 90	            }
 91	        }
 92	        // If the animal is immune and not infected, there is a chance
 93	        // of losing immunity.
 94	        else
 95	        {
 96	            if(rand.nextDouble() <= (immuneProbability / 15)) {
 97	                immune = false;
 98	            }
 99	        }
100	        
101	        if(isAlive()) 
102	        {
103	            if(!getIsImmune() && !getIsInfected())
104	            {
105	                // checks to see if the animal is going to catch a disease from
106	                // its surroundings.
107	
108	                if (surroundingsInfected() && rand.nextDouble() <= diseaseSpreadProbability)
109	                {
110	                    infected = true;
111	                }
112	                
113	                // checks to see if the animal is going to get a disease out 
114	                // of nowhere.
115	                else if (rand.nextDouble() <= diseaseProbability) 
116	                {
117	                    infected = true;           
118	                }
119	            }
120	            
121	            // checks to see if the animal is able to give birth
122	            if(this.getIsFemale()) 
123	            {
124	                if(canBreed() && rand.nextDouble() <= breedingProbability)
125	                {
126	                    populate(newAnimals);
127	                }
128	            }
129	
130	            // Move towards a source of food if found.
131	            Location newLocation = findFood();
132	            
133	            if(newLocation == null) 
134	            { 
135	                Location possibleNewLocation = getField().freeAdjacentLocation(getLocation(), Animal.class);
136	                
137	                if (possibleNewLocation == null) 
138	                {
139	                    // no free adjacent locations therefore it is 
140	                    // overcrowded
141	                    if (rand.nextDouble() < 0.3) 
142	                    {
143	                        setDead();
144	                    }
145	                }
146	                
147	                // No food found and there is a free location - move there.
148	                if (rand.nextDouble() <= movementProbability) 
149	                {
150	                    newLocation = possibleNewLocation;
151	                }
152	            }
153	            
154	            // Move to new location
155	            if(newLocation != null)
156	            { 
157	                setLocation(newLocation);
158	            }
159	        }
160	    }
161	    
162	    /**
163	     * Look for food adjacent to the current location.
164	     * Only the first live prey or plant is eaten.
165	     * 
166	     * @return Where food was found, or null if it wasn't.
167	     */
168	    abstract protected Location findFood();
169	
170	    /**
171	     * Create a new instance of the current species.
172	     *
173	     * @param location Where the offspring should be placed.
174	     * @param isInfected Whether the offspring starts infected.
175	     * @param isImmune Whether the offspring starts immune.
176	     * @return A new offspring of the current species.
177	     */
178	    protected abstract Animal createOffspring(Location location, boolean isInfected, boolean isImmune);
179	
180	    /**
181	     * @Override
182	     * 
183	     * Indicate that the animal is no longer alive.
184	     * It is removed from the field.
185	     */
186	    protected void setDead()
187	    {
188	        alive = false;
189	        
190	        if(location != null) 
191	        {
192	            field.clear(location, Animal.class);
193	            location = null;
194	        }
195	        
196	        if (this.getClass().equals(Lion.class) || this.getClass().equals(Cheetah.class)){
197	            location = null;
198	        }
199	    }
200	    
201	    /**
202	     * @Override
203	     * 
204	     * When called, the animal is killed and returns
205	     * its food value.
206	     * 
207	     * @return The food value of the animal eaten.
208	     */
209	    protected int beEaten() 
210	    {
211	        setDead();
212	        
213	        return foodValue;
214	    }
215	    
216	    /**
217	     * @Override
218	     * 
219	     * Place the animal at the new location in the given field.
220	     * 
221	     * @param newLocation The animal's new location.
222	     */
223	    protected void setLocation(Location newLocation)
224	    {
225	        if(location != null) 
226	        {
227	            if(field.getObjectAt(location, Animal.class) != null)
228	            {
229	                field.clear(location, Animal.class);
230	            }
231	        }
232	        
233	        location = newLocation;
234	        field.place(this, newLocation);
235	    }
236	    
237	    /**
238	     * Returns the gender of the animal.
239	     * 
240	     * @return Returns true if female.
241	     */
242	    protected boolean getIsFemale() 
243	    {
244	        return isFemale;
245	    }
246	    
247	    /**
248	     * @Override
249	     * 
250	     * Increase the age.
251	     * This could result in the Animal's death.
252	     */
253	    protected void incrementAge()
254	    {
255	        age++;
256	        if(age > maxAge) {
257	            setDead();
258	        }
259	    }
260	    
261	    /**
262	     * Make this animal's more hungry. This could result in the animal's death.
263	     */
264	    protected void incrementHunger()
265	    {
266	        foodLevel--;
267	        if(foodLevel <= 0) {
268	            setDead();
269	        }
270	    }
271	    
272	    /**
273	     * @Override
274	     * 
275	     * New births will be made into free adjacent locations.
276	     * @param newAnimals A list to return newly born Animals.
277	     */
278	    protected void populate(List<LivingOrganism> newAnimals)
279	    {
280	        // Get a list of adjacent free locations.
281	        Field field = getField();
282	        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Animal.class);
283	        //determines the number of offspring the animal will produce
284	        
285	        int births = breed();
286	        // New animals are born into adjacent locations.
287	        
288	        for(int b = 0; b < births && free.size() > 0; b++) 
289	        {
290	            Location loc = free.remove(0);
291	            boolean offspringIsInfected = infected;
292	            boolean offspringIsImmune = immune;
293	            
294	            // If the mother is infected, the child has a small chance of starting immune instead.
295	            if (!immune && infected && rand.nextDouble() < 0.15) 
296	            {
297	                offspringIsImmune = true;
298	                offspringIsInfected = false;
299	            }
300	            // Immune mothers usually have children that are not immune.
301	            else if (immune && rand.nextDouble() < 0.9)
302	            {
303	                offspringIsImmune = false;
304	            }
305	            
306	            Animal newAnimal = createOffspring(loc, offspringIsInfected, offspringIsImmune);
307	            newAnimals.add(newAnimal);
308	        }
309	    }
310	    
311	    /**
312	     * Generate a number representing the number of births,
313	     * if it can breed.
314	     * 
315	     * @return The number of births (may be zero).
316	     */
317	    protected int breed()
318	    {
319	        int births = 0;
320	        
321	        Field field = getField();
322	        List<Location> adjacent = field.adjacentLocations(getLocation());
323	        Iterator<Location> it = adjacent.iterator();
324	        
325	        while(it.hasNext()) 
326	        {
327	            Location where = it.next();
328	            Animal animal = (Animal) field.getObjectAt(where, Animal.class);
329	            Class typeOfOtherAnimal = null;
330	            
331	            if (field.getObjectAt(where, Animal.class) != null) 
332	            {
333	                typeOfOtherAnimal  = field.getObjectAt(where, Animal.class).getClass();
334	            }
335	            
336	            //checks to make sure they are of the same species
337	            if(this.getClass().equals(typeOfOtherAnimal)) 
338	            {
339	                //checks to make the other animal is also a male
340	                if(animal.getIsFemale() == false) 
341	                {
342	                    births = rand.nextInt(maxLitterSize) + 1;
343	                }
344	            }
345	        }
346	        
347	        return births;
348	    }
349	
350	    /**
351	     * An Animal can breed if it has reached the breeding age.
352	     * 
353	     * @return true if the Animal can breed, false otherwise.
354	     */
355	    protected boolean canBreed()
356	    {
357	        return age >= breedingAge;
358	    }
359	
360	    /**
361	     * Set the shared species-level characteristics for an animal.
362	     */
363	    protected final void configureAnimal(int breedingAge, int maxAge, double breedingProbability,
364	                                         int maxLitterSize, int maxFoodLevel, int foodValue)
365	    {
366	        this.breedingAge = breedingAge;
367	        this.maxAge = maxAge;
368	        this.breedingProbability = breedingProbability;
369	        this.maxLitterSize = maxLitterSize;
370	        this.maxFoodLevel = maxFoodLevel;
371	        this.foodValue = foodValue;
372	    }
373	
374	    /**
375	     * Initialise age and hunger state for either a newborn or a random starting animal.
376	     */
377	    protected final void initializeAgeAndFood(boolean randomAge, int newbornFoodLevel)
378	    {
379	        if (randomAge) 
380	        {
381	            age = rand.nextInt(maxAge);
382	            foodLevel = rand.nextInt(maxFoodLevel);
383	        }
384	        else
385	        {
386	            age = 0;
387	            foodLevel = newbornFoodLevel;
388	        }
389	    }
390	    
391	    /**
392	     * @return Returns the status of the animal being infected or not
393	     */
394	    public boolean getIsInfected() 
395	    {
396	        return infected;
397	    }
398	    
399	    /**
400	     * @return Returns the status of the animal being immune or not
401	     */
402	    public boolean getIsImmune() 
403	    {
404	        return immune;
405	    }
406	    
407	    /**
408	     * Checks all the surroundings to see if there any animals which are infected.
409	     * 
410	     * @return Returns true if there is a surrounding animal which is infected.
411	     */
412	    protected boolean surroundingsInfected()
413	    {
414	        boolean surroundingsAreInfected = false;
415	        
416	        Field field = getField();
417	        List<Location> adjacent = field.adjacentLocations(getLocation());
418	        Iterator<Location> it = adjacent.iterator();
419	        
420	        while(it.hasNext() && ! surroundingsAreInfected) 
421	        {
422	            Location where = it.next();
423	            Animal animal = (Animal) field.getObjectAt(where, Animal.class);
424	            
425	            if (field.getObjectAt(where, Animal.class) != null) 
426	            {
427	                if (animal.getIsInfected())
428	                {
429	                    surroundingsAreInfected = true;
430	                }
431	            }
432	        }
433	        
434	        return surroundingsAreInfected;
435	    }
436	}

