  3	/**
  4	 * A class representing the shared characteristics between predators
  5	 *
  6	 * @version 25/02/2022
  7	 */
  8	public abstract class Predator extends Animal
  9	{
 10	    // The likelihood of the predator catching its prey
 11	    protected double preyCatchingProbability;
 12	
 13	    /**
 14	     * Create a new predator at location in field.
 15	     * 
 16	     * @param field The field currently occupied.
 17	     * @param location The location within the field.
 18	     * @param infected : intial state if the prey is infected or not
 19	     * @param immmune : intial state if the prey is immune or not
 20	     */
 21	    protected Predator(Field field, Location location, boolean isInfected, boolean isImmune)
 22	    {
 23	        super(field, location, isInfected, isImmune);
 24	        movementProbability = 0.8;
 25	    }
 26	
 27	    /**
 28	     * Set the shared species-level characteristics for a predator.
 29	     */
 30	    protected final void configurePredator(int breedingAge, int maxAge, double breedingProbability,
 31	                                           int maxLitterSize, int maxFoodLevel, int foodValue,
 32	                                           double preyCatchingProbability)
 33	    {
 34	        configureAnimal(breedingAge, maxAge, breedingProbability, maxLitterSize, maxFoodLevel, foodValue);
 35	        this.preyCatchingProbability = preyCatchingProbability;
 36	    }
 37	
 38	    /**
 39	     * Predators start newborn life at a low random hunger level.
 40	     */
 41	    protected final int getNewbornFoodLevel()
 42	    {
 43	        double percentageOfMaxFoodLevel = rand.nextDouble() / 5.5;
 44	        return (int) (percentageOfMaxFoodLevel * maxFoodLevel);
 45	    }
 46	    
 47	    /**
 48	     * @Override
 49	     * 
 50	     * This is what the predators does most of the time - it may move around, it eats prey, 
 51	     * it may breed, it may get infected with a disease, it may become immune to that disease, 
 52	     * it may die of the disease, it may die of hunger, and it may die of old age.
 53	     * 
 54	     * @param newPredators A list to return newly born prey.
 55	     */
 56	    public void act(List<LivingOrganism> newPredators)
 57	    {
 58	        // Predators have a lower chance of acting when its night
 59	        if(getTime().isNight()) 
 60	        {
 61	            if (rand.nextDouble() > 0.25)
 62	            {
 63	                return;
 64	            }
 65	        }
 66	        
 67	        // Predators have a lower chance of acting when its foggy
 68	        if (getWeather().getWeather() == Weather.WeatherType.Foggy) 
 69	        {
 70	            if (rand.nextDouble() > 0.50)
 71	            {
 72	                return;
 73	            }
 74	        }
 75	
 76	        super.act(newPredators);
 77	    }
 78	    
 79	    /**
 80	     * @Override
 81	     * 
 82	     * Look for prey adjacent to the current location.
 83	     * Eats prey till full.
 84	     * Predators may catch the prey's disease if eaten.
 85	     * 
 86	     * @return Where food was found, or null if it wasn't.
 87	     */
 88	    protected Location findFood()
 89	    {
 90	        Field field = getField();
 91	        List<Location> adjacent = field.adjacentLocations(getLocation());
 92	        Iterator<Location> it = adjacent.iterator();
 93	        
 94	        while(it.hasNext()) 
 95	        {
 96	            Location where = it.next();
 97	            Object animal = field.getObjectAt(where, Animal.class);
 98	            
 99	            if(animal instanceof Prey) 
100	            {
101	                Prey prey = (Prey) animal;
102	                if(prey.isAlive() && foodLevel < maxFoodLevel && rand.nextDouble() < preyCatchingProbability) 
103	                { 
104	                    // Predator is hungry and prey is availiable so eat
105	                    // the prey.
106	                    int preyFoodValue = prey.beEaten();
107	                    foodLevel += preyFoodValue;
108	                    
109	                    // if the prey being eaten is infected then the predator most likely
110	                    // gets infected
111	                    if (prey.getIsInfected() && !getIsImmune() && rand.nextDouble() <= diseaseSpreadProbability)
112	                    {
113	                        this.infected = true; 
114	                    }
115	                    
116	                    return where;
117	                }
118	            }
119	        }
120	        
121	        return null;
122	    }
123	}

