 57	        Iterator<Location> it = adjacent.iterator();
 58	        
 59	        while(it.hasNext()) 
 60	        {
 61	            Location where = it.next();
 62	            
 63	            // Get the plant and animal currently at this new location.
 64	            Plant plant = (Plant) field.getObjectAt(where, Plant.class);
