 3	/**
 4	 * Mixin for organisms that move through the field.
 5	 *
 6	 * @version 26/02/2022
 7	 */
 8	public interface Movable extends OrganismContext
 9	{
10	    Random RANDOM = Randomizer.getRandom();
11	
12	    MovementState getMovementState();
13	
14	    Location locateFoodSource();
15	
16	    void relocate(Location newLocation);
17	
18	    default void moveOneStep()
19	    {
20	        Location newLocation = locateFoodSource();
21	
22	        if(newLocation == null) 
23	        { 
24	            Location possibleNewLocation = currentField().freeAdjacentLocation(currentLocation(), Animal.class);
25	
26	            if (possibleNewLocation == null) 
27	            {
28	                if (RANDOM.nextDouble() < 0.3) 
29	                {
30	                    markDead();
31	                }
32	            }
33	
34	            if (RANDOM.nextDouble() <= getMovementState().getMovementProbability()) 
35	            {
36	                newLocation = possibleNewLocation;
37	            }
38	        }
39	
40	        if(newLocation != null && organismIsAlive())
41	        { 
42	            relocate(newLocation);
43	        }
44	    }
45	}

