 6	public interface HungerBased extends OrganismContext
 7	{
 8	    HungerState getHungerState();
 9	
10	    default void digestOneStep()
11	    {
12	        HungerState hungerState = getHungerState();
13	        hungerState.setFoodLevel(hungerState.getFoodLevel() - 1);
14	
15	        if(hungerState.getFoodLevel() <= 0) {
16	            markDead();
17	        }
18	    }
19	
20	    default boolean isHungry()
21	    {
