 5	/**
 6	 * Mixin for organisms that reproduce through nearby free locations.
 7	 *
 8	 * @version 26/02/2022
 9	 */
10	public interface Breedable extends OrganismContext, Ageable
11	{
12	    Random RANDOM = Randomizer.getRandom();
13	
14	    BreedingState getBreedingState();
15	
16	    DiseaseState getDiseaseState();
17	
18	    Animal spawnOffspring(Location location, boolean isInfected, boolean isImmune);
19	
20	    default boolean canBreedNow()
21	    {
22	        return getAgeState().getAge() >= getBreedingState().getBreedingAge();
23	    }
24	
25	    default void populateOffspring(List<LivingOrganism> newAnimals)
26	    {
27	        Field field = currentField();
28	        List<Location> free = field.getFreeAdjacentLocations(currentLocation(), Animal.class);
29	        int births = calculateBirths();
30	
31	        for(int b = 0; b < births && free.size() > 0; b++) 
32	        {
33	            Location loc = free.remove(0);
34	            DiseaseState diseaseState = getDiseaseState();
35	            boolean offspringIsInfected = diseaseState.isInfected();
36	            boolean offspringIsImmune = diseaseState.isImmune();
37	
38	            if (!diseaseState.isImmune() && diseaseState.isInfected() && RANDOM.nextDouble() < 0.15) 
39	            {
40	                offspringIsImmune = true;
41	                offspringIsInfected = false;
42	            }
43	            else if (diseaseState.isImmune() && RANDOM.nextDouble() < 0.9)
44	            {
45	                offspringIsImmune = false;
46	            }
47	
48	            newAnimals.add(spawnOffspring(loc, offspringIsInfected, offspringIsImmune));
49	        }
50	    }
51	
52	    default int calculateBirths()
53	    {
54	        Field field = currentField();
55	        List<Location> adjacent = field.adjacentLocations(currentLocation());
56	        Iterator<Location> it = adjacent.iterator();
57	
58	        while(it.hasNext()) 
59	        {
60	            Location where = it.next();
61	            Animal animal = field.getObjectAt(where, Animal.class);
62	
63	            if (animal != null && this.getClass().equals(animal.getClass())) 
64	            {
65	                if(!animal.getBreedingState().isFemale()) 
66	                {
67	                    return RANDOM.nextInt(getBreedingState().getMaxLitterSize()) + 1;
68	                }
69	            }
70	        }
71	
72	        return 0;
73	    }
74	}

