 5	/**
 6	 * Mixin for organisms that can catch, spread, and recover from disease.
 7	 *
 8	 * @version 26/02/2022
 9	 */
10	public interface DiseaseProne extends OrganismContext
11	{
12	    Random RANDOM = Randomizer.getRandom();
13	
14	    DiseaseState getDiseaseState();
15	
16	    default void updateDiseaseState()
17	    {
18	        DiseaseState diseaseState = getDiseaseState();
19	
20	        if (!diseaseState.isImmune() && diseaseState.isInfected()) 
21	        {
22	            if(RANDOM.nextDouble() <= diseaseState.getDeathFromInfectionProbability()) 
23	            {
24	                markDead();            
25	            }
26	            else if(RANDOM.nextDouble() <= diseaseState.getImmuneProbability()) {
27	                diseaseState.setImmune(true);
28	                diseaseState.setInfected(false);
29	            }
30	        }
31	        else
32	        {
33	            if(RANDOM.nextDouble() <= (diseaseState.getImmuneProbability() / 15)) {
34	                diseaseState.setImmune(false);
35	            }
36	        }
37	    }
38	
39	    default void exposeToDisease()
40	    {
41	        DiseaseState diseaseState = getDiseaseState();
42	
43	        if(!diseaseState.isImmune() && !diseaseState.isInfected())
44	        {
45	            if (surroundingsInfected() && RANDOM.nextDouble() <= diseaseState.getDiseaseSpreadProbability())
46	            {
47	                diseaseState.setInfected(true);
48	            }
49	            else if (RANDOM.nextDouble() <= diseaseState.getDiseaseProbability()) 
50	            {
51	                diseaseState.setInfected(true);           
52	            }
53	        }
54	    }
55	
56	    default boolean surroundingsInfected()
57	    {
58	        Field field = currentField();
59	        List<Location> adjacent = field.adjacentLocations(currentLocation());
60	        Iterator<Location> it = adjacent.iterator();
61	        
62	        while(it.hasNext()) 
63	        {
64	            Location where = it.next();
65	            Animal animal = field.getObjectAt(where, Animal.class);
66	
67	            if (animal != null && animal.getDiseaseState().isInfected()) 
68	            {
69	                return true;
70	            }
71	        }
72	        
73	        return false;
74	    }
75	}
